      if (lookahead == '>') ADVANCE(19);
      END_STATE();
    case 9:
      ACCEPT_TOKEN(anon_sym_LT);
      END_STATE();
    case 10:
      ACCEPT_TOKEN(anon_sym_COMMA);
      END_STATE();
    case 11:
      ACCEPT_TOKEN(anon_sym_GT);
      END_STATE();
    case 12:
